  padding-block: clamp(4rem, 9vw, 8rem);
  border-block: 1px solid var(--line);
}

.marquee {
  display: flex;
  overflow: hidden;
  white-space: nowrap;
  user-select: none;
  mask-image: linear-gradient(90deg, transparent, #000 12%, #000 88%, transparent);
}

.marquee + .marquee { margin-top: clamp(0.8rem, 2vw, 1.4rem); }

.marquee-track {
  display: flex;
  align-items: center;
  min-width: max-content;
  animation: marquee-left 31s linear infinite;
  will-change: transform;
}

.marquee.reverse .marquee-track { animation-name: marquee-right; animation-duration: 35s; }
.marquee.slow .marquee-track { animation-duration: 39s; }

.marquee span {
  display: inline-flex;
  align-items: center;
  gap: clamp(1.2rem, 3vw, 2.8rem);
  padding-right: clamp(1.2rem, 3vw, 2.8rem);
  font-family: var(--font-serif);
  font-size: clamp(3rem, 9vw, 8.5rem);
  font-weight: 800;
  letter-spacing: -0.07em;
  line-height: 0.95;
}

.marquee span::after {
  content: '◦';
  color: var(--terracotta);
  font-family: var(--font-sans);
  font-size: 0.45em;
  transform: translateY(-0.06em);
}

@keyframes marquee-left {
  from { transform: translate3d(0,0,0); }
  to { transform: translate3d(-50%,0,0); }
}

@keyframes marquee-right {
  from { transform: translate3d(-50%,0,0); }
  to { transform: translate3d(0,0,0); }
}

.about-section,
.philosophy,
.service-details,
.clients-intro,
.letter-wrap,
.contact-hero {
  padding: var(--section) var(--gutter);
}

.about-grid {
  display: grid;
  grid-template-columns: minmax(9rem, 0.8fr) minmax(18rem, 1.55fr);
  gap: clamp(3rem, 10vw, 14rem);
