  font-family: var(--font-serif);
  font-size: clamp(1.38rem, 2.2vw, 2.25rem);
  line-height: 1.46;
}

.dropcap::first-letter {
  float: left;
  padding-right: 0.12em;
  font-family: var(--font-serif);
  font-size: 5.2em;
  font-weight: 800;
  line-height: 0.78;
  color: var(--terracotta);
}

.philosophy {
  display: grid;
  grid-template-columns: minmax(14rem, 1fr) minmax(18rem, 1.05fr);
  gap: clamp(3rem, 9vw, 10rem);
  min-height: 72vh;
  align-items: center;
}

.philosophy-title {
  margin: 0;
  font-family: var(--font-serif);
  font-size: clamp(4.1rem, 10vw, 10rem);
  font-weight: 800;
  line-height: 0.9;
  letter-spacing: -0.07em;
}

.warm-divider {
  width: calc(100% - var(--gutter) * 2);
  height: 1px;
  margin-inline: var(--gutter);
  background: var(--line);
}

.service-details {
  display: grid;
  grid-template-columns: minmax(15rem, 0.82fr) minmax(18rem, 1.4fr);
  gap: clamp(3rem, 9vw, 10rem);
}

.question {
  margin: 0;
  max-width: 10ch;
  font-family: var(--font-serif);
  font-size: clamp(3.1rem, 7vw, 7rem);
  line-height: 0.95;
  letter-spacing: -0.06em;
}

.service-list {
  display: grid;
  gap: clamp(2.2rem, 5vw, 5rem);
}

.service-item h2,
.client-card h2 {
  margin: 0 0 0.8rem;
  font-family: var(--font-serif);
  font-weight: 800;
  letter-spacing: -0.045em;
  line-height: 1;
}

.service-item h2 { font-size: clamp(2.5rem, 4.5vw, 5rem); }
.service-item p { margin: 0; }

.clients-intro {
  padding-bottom: clamp(3rem, 7vw, 6rem);
}

.clients-intro .page-title { max-width: none; }

.clients-subtitle {
  margin: 1.5rem 0 0 auto;
  max-width: 22rem;
  color: var(--muted);
  font-size: clamp(1rem, 1.3vw, 1.25rem);
}

.clients-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  border-top: 1px solid var(--line);
  border-left: 1px solid var(--line);
  margin: 0 var(--gutter) var(--section);
}

.client-card {
  min-height: clamp(15rem, 22vw, 24rem);
  padding: clamp(1.5rem, 3vw, 3rem);
  border-right: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  transition: background 220ms ease;
}

.client-card:hover { background: rgba(255,255,255,0.24); }

.client-card h2 { font-size: clamp(2rem, 3.5vw, 4.4rem); }
.client-card p { margin: 0; color: var(--muted); font-size: 0.98rem; line-height: 1.6; }

.contact-hero {
  min-height: calc(100vh - 5.5rem);
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  text-align: center;
}

.contact-title {
  font-size: clamp(5.4rem, 23vw, 24rem);
  line-height: 0.78;
}

.contact-links {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: clamp(1.2rem, 4vw, 3.5rem);
  margin-top: clamp(3rem, 7vw, 6rem);
  color: var(--muted);
  font-size: clamp(1.1rem, 1.6vw, 1.5rem);
  font-weight: 700;
}

.site-footer {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  padding: 1.5rem var(--gutter) 2rem;
  color: var(--muted);
  font-size: 0.86rem;
  border-top: 1px solid var(--line);
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
    transition-duration: 0.001ms !important;
  }
}

@media (max-width: 900px) {
  .primary-nav { display: none; }
  .menu-toggle { display: inline-block; }
  .hero { min-height: 60vh; }
  .media-showcase { grid-template-columns: 1fr; }
  .media-block,
  .media-block:nth-child(2) { min-height: 18rem; transform: none; }
  .about-grid,
  .letter-wrap,
  .philosophy,
  .service-details { grid-template-columns: 1fr; }
  .letter-kicker { position: static; }
  .clients-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

@media (max-width: 620px) {
  .site-header { padding-block: 0.85rem; }
  .hero-title { font-size: clamp(4.1rem, 20vw, 7rem); }
  .page-title { font-size: clamp(4rem, 18vw, 6rem); }
  .marquee span { font-size: clamp(3.1rem, 18vw, 6rem); }
  .about-section,
  .philosophy,
  .service-details,
  .clients-intro,
  .letter-wrap,
  .contact-hero { padding-block: clamp(4rem, 18vw, 7rem); }
  .clients-grid { grid-template-columns: 1fr; }
  .client-card { min-height: 13rem; }
  .site-footer { flex-direction: column; }
  .contact-links { flex-direction: column; }
}
EOF

